@import "@fontsource-variable/instrument-sans";
@import "@fontsource/dm-mono/400.css";
@import "@fontsource/dm-mono/500.css";

/* Light (faithful): off-white page, a flat grey second band, near-black ink, orange as the
   loud accent (highlight) and a utility blue for form buttons (primary). */
:root {
  --background: oklch(0.987 0 0);
  --foreground: oklch(0.18 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.18 0 0);
  --popover: oklch(0.987 0 0);
  --popover-foreground: oklch(0.18 0 0);
  --primary: oklch(0.575 0.2 254);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.925 0 0);
  --secondary-foreground: oklch(0.18 0 0);
  --muted: oklch(0.961 0 0);
  --muted-foreground: oklch(0.76 0 0);
  --accent: oklch(0.961 0 0);
  --accent-foreground: oklch(0.18 0 0);
  --destructive: oklch(0.6 0.22 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.18 0 0 / 12%);
  --input: oklch(0.18 0 0 / 10%);
  --ring: oklch(0.575 0.2 254);
  --highlight: oklch(0.7 0.19 42);
  --highlight-foreground: oklch(0.18 0 0);
  --glow: oklch(0.82 0.08 60);
  --chart-1: oklch(0.7 0.19 42);
  --chart-2: oklch(0.575 0.2 254);
  --chart-3: oklch(0.18 0 0);
  --chart-4: oklch(0.76 0 0);
  --chart-5: oklch(0.85 0.1 70);
  --sidebar: oklch(0.961 0 0);
  --sidebar-foreground: oklch(0.18 0 0);
  --sidebar-primary: oklch(0.575 0.2 254);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.925 0 0);
  --sidebar-accent-foreground: oklch(0.18 0 0);
  --sidebar-border: oklch(0.18 0 0 / 12%);
  --sidebar-ring: oklch(0.575 0.2 254);

  --typeface-body: "Instrument Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: "DM Mono", ui-monospace, Menlo, monospace;
  --radius: 0.625rem;
  --page-width: 90rem;
  --page-gutter: 1.5rem;
  --section-y: 3rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 7rem;
  }
}

/* Dark sibling: ink-black page, a slightly lifted second band, the same orange and blue. */
.dark {
  --background: oklch(0.17 0 0);
  --foreground: oklch(0.96 0 0);
  --card: oklch(0.24 0 0);
  --card-foreground: oklch(0.96 0 0);
  --popover: oklch(0.2 0 0);
  --popover-foreground: oklch(0.96 0 0);
  --primary: oklch(0.64 0.18 254);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.29 0 0);
  --secondary-foreground: oklch(0.96 0 0);
  --muted: oklch(0.21 0 0);
  --muted-foreground: oklch(0.58 0 0);
  --accent: oklch(0.24 0 0);
  --accent-foreground: oklch(0.96 0 0);
  --destructive: oklch(0.68 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 14%);
  --input: oklch(1 0 0 / 14%);
  --ring: oklch(0.64 0.18 254);
  --highlight: oklch(0.7 0.19 42);
  --highlight-foreground: oklch(0.17 0 0);
  --glow: oklch(0.45 0.1 50);
  --chart-1: oklch(0.7 0.19 42);
  --chart-2: oklch(0.64 0.18 254);
  --chart-3: oklch(0.96 0 0);
  --chart-4: oklch(0.58 0 0);
  --chart-5: oklch(0.85 0.1 70);
  --sidebar: oklch(0.21 0 0);
  --sidebar-foreground: oklch(0.96 0 0);
  --sidebar-primary: oklch(0.64 0.18 254);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.29 0 0);
  --sidebar-accent-foreground: oklch(0.96 0 0);
  --sidebar-border: oklch(1 0 0 / 14%);
  --sidebar-ring: oklch(0.64 0.18 254);
}
